// Allowed rating values. Anything else counts as a failed rating.
const allowed = ['High', 'Medium', 'Low', 'Reject'];

// The lead as it arrived in this workflow
const lead = $('Receive Leads').item.json;

const quality = String($json.output?.quality || '');
const qualityReason = String($json.output?.qualityReason || '');

// Stop if the rating is missing or not one of the allowed values
if (!allowed.includes(quality)) {
  throw new Error('Invalid rating for ' + lead.companyName + ': ' + quality);
}

// Return the same lead plus the rating
return { json: { ...lead, quality: quality, qualityReason: qualityReason } };
